WHOLE = {'facade_plan.py': '"""A facade\'s composition, decided for one face over every storey where its openings are chosen (0.238.0; the\nfactory\'s roadmap 79 and its `docs/proposals/FACADE_PLANNER.md`).\n\nWHY HERE AND NOT IN THE EMITTER. `_exterior` emits each side of each storey on its own, and `_emit_wall_run` is handed\none run with its openings already placed as fractions of it (`_opening_to_hole`), so nothing downstream of the spec can\nalign two storeys: it never sees two. A face is decided where its openings are first chosen -- a preset writing a spec,\nor a migration over the specs -- and this module is that place. The emitter stays the executor.\n\nWHAT THE LIBRARY WAS, measured (the factory\'s `docs/findings/facade_census_79/`, on the 102 buildings a themed lot can\ndraw): of the 169 first-storey openings in its 52 multi-storey buildings, 28 stood over a ground-floor opening; the\nEmpties, whose presets lay every storey on one list of bays, read 92.9 % through the same instrument. The upper storeys\nwere authored mirrored about their face\'s centre (167 of 177 openings) and the ground floors for the rooms behind them\n(135 of 321), so while the ground floor holds, stacking and symmetry trade against each other.\n\nTHE ROWS. A row is one family\'s composition, and each names where it came from -- the grammar is not invented here (the\nfactory\'s roadmap 79 forbids that, and is right to). The walker\'s references: "Align repeated architecture where\nconstruction would align it; vary the parts that would actually vary" (the factory\'s\n`docs/reference/HUMAN_AUTHORSHIP_GUIDE.md`), and the Empties\' comps (`docs/reference/EMPTIES_COMPS.md`, agreed\n2026-10-04): a rowhome is "two windows per storey, stacked on the same bays".\n\n  * `rowhome` -- two bays, each a fixed fraction off the front\'s centre, wider on a wider house. Was inline in\n    `presets.empty_rowhome` (the Empties, 0.174.0); its output is unchanged, to the byte.\n  * `midrise` -- round(width / bay) equal bays, at least two, the door in the bay nearest the lobby. Was inline in\n    `presets.empty_midrise` (0.213.0, the two-bay floor 0.217.0); unchanged, to the byte.\n  * `stack_mirrored` -- the library\'s upper storeys moved onto the openings below them, in mirrored pairs, within a bay\n    (below). The first composition this module applies to buildings it did not write.\n\nSTACK_MIRRORED, the rule (`migrate_facade_stack.py` runs it over the specs). Per face, storeys upward, each against\nthe storey below as it now stands:\n  * only an upper-storey WINDOW with no `tag` moves; every ground-floor opening, every door, breach, garage, vault\n    or tagged window stays where gameplay put it, and a window keeps its kind, width, height and sill;\n  * a window with a partner mirrored about the face\'s centre (same width) moves only WITH it, onto two openings\n    below that are each other\'s mirror; a window on the centre line only onto an opening on it; any other window\n    onto the nearest opening below; each target within `REACH` and taken once;\n  * a target is turned down when the window would leave its run (`EDGE_WALLS` wall thicknesses from each end), come\n    within `MIN_PIER` of another opening on its storey, or stand over a partition\'s junction with the wall (a room\n    wall in the window) -- the window then tries the next one, and stays when none is left;\n  * HELD, never moved: a window a den\'s drape hangs over (`lights._drapes_window`\'s test, on the spec\'s own volume),\n    any window on a wall a fire escape serves (its access opening, `FireEscape.access`), every window of a face whose\n    storey extents differ from the storey below\'s (a setback: the mirror is not the same line), and a window whose\n    mirrored partner stays -- tagged, held, or not a window -- since moving one of the two alone would break the\n    symmetry the storey was authored with;\n  * an Empty (`facade`) is left alone: its row composed it, and its spec is its preset\'s own output. Run over one,\n    the rule would move each rowhome\'s rear window over its back door -- the preset puts them in the house\'s two\n    bays on purpose.\nMeasured before it ran (`docs/findings/facade_census_79/predict.py`, its `over sym` row): 46 windows in 22 buildings\nmove, a median 2.0 m and at most 3.0, none into another room; stacking goes from 28 to 74 of 169 and every mirrored\nopening stays mirrored.\n"""\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\n\nimport setbacks       # noqa: E402\nimport spec_loader    # noqa: E402\n\n#: The rows. Each names its source; a value is a call until the walker changes it.\nROWS = {\n    "rowhome": {\n        "source": "EMPTIES_COMPS.md, Family 1: two window bays a house; was inline in presets.empty_rowhome",\n        # a bay\'s centre, as a fraction of the front off its centre: the wide houses\' and the rest\n        "offset": 0.22, "offset_narrow": 0.2, "wide_from_m": 6.0,\n    },\n    "midrise": {\n        "source": "URBAN_MIDRISE_COMPS.md: regular windows; presets.MIDRISE_BAY (0.213.0), two-bay floor (0.217.0)",\n        "bay_m": 3.2, "min_bays": 2,\n    },\n}\n\n#: STACK_MIRRORED\'s dials. REACH: the one bay the library already chose (the mid-rise row\'s), so a window moves at\n#: most a bay. MIN_PIER: the least solid wall left between two openings on a storey. EDGE_WALLS: how many wall\n#: thicknesses a window keeps clear of its run\'s ends (half of one is the corner\'s own inset, `_emit_wall_run`).\nREACH = ROWS["midrise"]["bay_m"]\nMIN_PIER = 0.3\nEDGE_WALLS = 1.5\n#: Two centres this close along a face are one line: the specs\' openings are on a 0.5 m grid.\nTOL = 0.05\n#: FRONTS A FAMILY COMPOSES (0.296.0): the presets whose street face stands on a row\'s bays on every upper storey,\n#: people\'s rooms behind it or not. The walker, of the slice\'s card shop -- two 1.4 m windows on a 20 m front over an\n#: apartment, beside a bank whose upper storey stands on 3.0 m bays -- asked whether it should get a proper window\n#: rhythm: "yes to window rhythm". Every window on a storey people reach is a sightline out over the street, so this\n#: is a family\'s call and not the library\'s: a family is added here by name, with its source.\nFRONT_ROWS = {\n    "card_shop": "midrise",     # the walker, 2026-10-31: the slice\'s card shop, an apartment over the shop\n}\n#: The face a Deli Counter building turns to its street (Level Factory stands every front door to the road, and the\n#: presets put the door on the south wall).\nFRONT = "S"\nDRAPE_NAME = "window_drape"\n\n\ndef unreached_storeys(spec):\n    """The upper storeys nobody can stand on (0.295.0): no room is on them, and no stair, ladder, ramp or fire escape\n    arrives at or passes them. A link reaches every storey from its lower end to its upper one, which can only call a\n    storey reached that a switchback does not stop at -- never the other way. Storey 0 is the street and always\n    reached; a basement is never upper."""\n    reached = {int(r.story) for r in spec.rooms}\n    for link in list(spec.stairs) + list(spec.ladders) + list(spec.ramps):\n        a, b = sorted((int(link.from_story), int(link.to_story)))\n        reached.update(range(a, b + 1))\n    for fe in spec.fire_escapes:\n        reached.update(int(s) for s in fe.served_stories)\n    return [s for s in range(1, int(spec.n_stories)) if s not in reached]\n\n\ndef _snap_sym(v, grid):\n    """`v` to the grid, symmetric about zero, so a mirrored pair of bays stays a mirrored pair."""\n    return (1 if v >= 0 else -1) * round(abs(v) / grid) * grid\n\n\ndef compose_unreached(d):\n    """A STOREY NOBODY REACHES IS A FACADE (0.295.0), composed on the mid-rise row. The walker\'s slice, the bank: its\n    upper storey has no room and no stair, and stood two 1.6 m windows on each 30 m and 22 m face -- a warehouse\'s\n    rhythm on a bank. The library\'s 70 multi-storey buildings carry a median 20 m of upper wall a window (the factory\'s\n    `docs/findings/slice_look/`, slice 22); a street\'s offices are 3 to 4. On a storey nobody can stand on, nothing a\n    window does to play -- a sightline, a route, a room\'s furnishing -- can happen, so it is the one place a face can\n    be composed whole without a gameplay cost: each face\'s untagged windows go, and one window like its widest\n    stands at the centre of every `midrise` bay that `_fits`. A face with no untagged window stays as it was: nothing\n    asked for windows there. Every tagged window and every other opening stays where it was authored. Idempotent.\n    In place; returns ``[(wall, story, windows before, windows after)]``."""\n    if d.get("facade"):\n        return []\n    spec = spec_loader.spec_from_dict(d)\n    storeys = set(unreached_storeys(spec))\n    if not storeys:\n        return []\n    return _compose(d, spec, lambda side, story: story in storeys)\n\n\ndef compose_front(d):\n    """A FAMILY\'S STREET FACE ON ITS ROW (0.296.0): on a building whose preset `FRONT_ROWS` names, the `FRONT` face of\n    every upper storey people reach is composed as `compose_unreached` composes a storey nobody reaches -- its untagged\n    windows go and one like its widest stands at the centre of every bay that `_fits` -- and the windows stay clear\n    glass, onto the rooms behind them. A face is left as authored when a fire escape serves it or a drape hangs over\n    any of its windows (`_held`): both were placed for the windows that are there. Composed before cover and\n    furniture are laid (`presets.make`), so they are laid round the windows that are built; a spec composed\n    after it was furnished must be refurnished. Idempotent. In place; returns ``[(wall, story, before, after)]``."""\n    if d.get("facade") or FRONT_ROWS.get(d.get("preset")) != "midrise":\n        return []\n    spec = spec_loader.spec_from_dict(d)\n    nobody = set(unreached_storeys(spec))\n    sh = float(spec.story_height)\n\n    def pick(side, story):\n        if side != FRONT or story < 1 or story in nobody:\n            return False\n        for i, w in enumerate(d.get("ext_walls") or []):\n            if w["wall"] != side or int(w["story"]) != story:\n                continue\n            run, centre, line = _run(spec, side, story)\n            for o, ob in zip(w.get("openings") or [], spec.ext_walls[i].openings):\n                if o.get("kind") != "window" or o.get("tag"):\n                    continue\n                r = ob.resolved()\n                z = story * sh + float(r.get("sill") or 0.0) + float(r.get("height") or 0.0) / 2.0\n                if _held(spec, d, side, story, float(ob.pos) * run, float(r["width"]), centre, line, z):\n                    return False\n        return True\n\n    return _compose(d, spec, pick)\n\n\ndef _compose(d, spec, pick):\n    """Each face `pick(side, story)` names, its untagged windows re-laid one to a `midrise` bay; the body of\n    `compose_unreached` and `compose_front`."""\n    grid = float(spec.grid)\n    wt = float(spec.wall_thick)\n    out = []\n    for i, w in enumerate(d.get("ext_walls") or []):\n        story = int(w["story"])\n        side = w["wall"]\n        if not pick(side, story):\n            continue\n        ops = w.get("openings") or []\n        objs = spec.ext_walls[i].openings\n        free = [j for j, o in enumerate(ops) if o.get("kind") == "window" and not o.get("tag")]\n        if not free:\n            continue\n        run, centre, line = _run(spec, side, story)\n        kept = [(_snap_sym(float(objs[j].pos) * run, grid), float(objs[j].resolved()["width"]))\n                for j in range(len(ops)) if j not in free]\n        proto = dict(ops[max(free, key=lambda j: float(objs[j].resolved()["width"]))])\n        width = float(objs[max(free, key=lambda j: float(objs[j].resolved()["width"]))].resolved()["width"])\n        junctions = _junctions(spec, side, story, centre, line)\n        placed = list(kept)\n        windows = []\n        # EQUAL BAYS ON THE BUILDER\'S GRID. The builder cuts every opening on `grid`, so `bay_positions`\' 30 / 9 =\n        # 3.33 m bays came out 3.5, 3.5, 3.0, 3.5 -- an uneven rhythm, which is what reads as generated. The mid-rise\n        # bay is rounded to two grid steps, so a row centred on the face lands on the grid at either count, and as\n        # many bays stand as keep a window clear of the corners.\n        bay = max(2.0 * grid, round(float(ROWS["midrise"]["bay_m"]) / (2.0 * grid)) * 2.0 * grid)\n        reach = run / 2.0 - EDGE_WALLS * wt - width / 2.0\n        n = max(0, 1 + int((2.0 * reach) / bay + 1e-9))\n        for k in range(n):\n            u = _snap_sym((k - (n - 1) / 2.0) * bay, grid)\n            if _fits(u, width, placed, run, wt, junctions) is None:\n                placed.append((u, width))\n                win = dict(proto)\n                win["pos"] = round(u / run, 6)\n                windows.append(win)\n        w["openings"] = [o for j, o in enumerate(ops) if j not in free] + windows\n        out.append((side, story, len(free), len(windows)))\n    return out\n\n\ndef bay_positions(row, width):\n    """The bay centres of `row` across a front `width` metres wide, as fractions of the front (-0.5..0.5)."""\n    r = ROWS[row]\n    if row == "rowhome":\n        bay = r["offset"] if float(width) >= r["wide_from_m"] else r["offset_narrow"]\n        return [-bay, bay]\n    if row == "midrise":\n        bays = max(r["min_bays"], int(round(float(width) / r["bay_m"])))\n        return [round((i + 0.5) / bays - 0.5, 4) for i in range(bays)]\n    raise KeyError(row)\n\n\ndef nearest(positions, toward):\n    """The index of the position nearest `toward` (the first of a tie)."""\n    return min(range(len(positions)), key=lambda i: abs(positions[i] - float(toward)))\n\n\ndef _near(x, xs):\n    return any(abs(x - y) <= TOL for y in xs)\n\n\ndef _run(spec, side, story):\n    """(run length, centre along the wall, wall line across it) of `side` on `story`, centrelines."""\n    x0, y0, x1, y1 = setbacks.storey_extent(spec, story)\n    if side in ("N", "S"):\n        return x1 - x0, (x0 + x1) / 2.0, (y1 if side == "N" else y0)\n    return y1 - y0, (y0 + y1) / 2.0, (x1 if side == "E" else x0)\n\n\ndef _junctions(spec, side, story, centre, line):\n    """Where the storey\'s partitions meet `side`, along the wall from its centre."""\n    wt = float(spec.wall_thick)\n    out = []\n    for p in spec.partitions:\n        if int(p.story) != story:\n            continue\n        a, b = sorted((float(p.start), float(p.end)))\n        if side in ("N", "S") and p.axis == "Y":\n            if (side == "N" and b >= line - wt) or (side == "S" and a <= line + wt):\n                out.append(float(p.pos) - centre)\n        elif side in ("E", "W") and p.axis == "X":\n            if (side == "E" and b >= line - wt) or (side == "W" and a <= line + wt):\n                out.append(float(p.pos) - centre)\n    return out\n\n\ndef _held(spec, d, side, story, u, w, centre, line, z):\n    """Why a window must not move, or None: a drape hangs over it, or a fire escape serves its wall."""\n    for fe in spec.fire_escapes:\n        if fe.wall == side and story in [int(s) for s in fe.served_stories]:\n            return "a fire escape serves its wall"\n    along = "x" if side in ("N", "S") else "y"\n    across = "y" if side in ("N", "S") else "x"\n    size = "size_x" if side in ("N", "S") else "size_y"\n    for v in d.get("volumes") or []:\n        if DRAPE_NAME not in str(v.get("name", "")):\n            continue\n        if (abs(float(v.get(along, 0.0)) - (centre + u)) <= max(float(v.get(size, 0.0)), w) / 2.0\n                and abs(float(v.get(across, 0.0)) - line) <= 1.0\n                and abs(float(v.get("z", 0.0)) - z) <= float(v.get("size_z", 0.0)) / 2.0 + 1.0):\n            return "a drape hangs over it"\n    return None\n\n\ndef _fits(t, w, others, run, wt, junctions):\n    if abs(t) + w / 2.0 > run / 2.0 - EDGE_WALLS * wt + 1e-9:\n        return "leaves the run"\n    for (u, ow) in others:\n        if abs(t - u) < (w + ow) / 2.0 + MIN_PIER - 1e-9:\n            return "too near another opening"\n    for j in junctions:\n        if abs(t - j) < w / 2.0 + wt / 2.0:\n            return "over a partition junction"\n    return None\n\n\ndef stack_mirrored(d, reach=REACH):\n    """Move `d`\'s upper-storey windows onto the openings below them, in mirrored pairs (the module\'s docstring), in\n    place. Returns ``(moves, held)``: ``moves`` [(wall, story, from_u, to_u)] in metres along the wall from its\n    centre, ``held`` [(wall, story, u, why)]."""\n    if d.get("facade"):\n        return [], []\n    spec = spec_loader.spec_from_dict(d)\n    grid = float(spec.grid)\n    wt = float(spec.wall_thick)\n    H = float(spec.story_height)\n\n    def snap(v):\n        return round(v / grid) * grid\n\n    rows = {}\n    for i, w in enumerate(d.get("ext_walls") or []):\n        rows[(w["wall"], int(w["story"]))] = (i, w)\n    moves, held = [], []\n    final = {}          # (side, story) -> the storey\'s opening positions as they now stand\n    for side in ("N", "S", "E", "W"):\n        stories = sorted(s for (sd, s) in rows if sd == side)\n        for story in stories:\n            if story < 1 or (side, story - 1) not in rows:\n                continue\n            i, wd = rows[(side, story)]\n            ib, _wb = rows[(side, story - 1)]\n            run, centre, line = _run(spec, side, story)\n            run_b, centre_b, _l = _run(spec, side, story - 1)\n            ops = spec.ext_walls[i].openings\n            here = [(snap(float(o.pos) * run), float(o.resolved()["width"]), o) for o in ops]\n            # the storey below AS IT NOW STANDS: a third storey stacks over the second\'s moved windows\n            below = final.get((side, story - 1),\n                              [snap(float(o.pos) * run_b) for o in spec.ext_walls[ib].openings])\n            movable, fixed = [], []\n            for j, (u, w, o) in enumerate(here):\n                if o.kind != "window" or o.tag:\n                    fixed.append((u, w))\n                    continue\n                r = o.resolved()\n                z = story * H + r["sill"] + r["height"] / 2.0\n                why = None\n                if abs(run - run_b) > 1e-6 or abs(centre - centre_b) > 1e-6:\n                    why = "the storey below stands on another extent"\n                else:\n                    why = _held(spec, d, side, story, u, w, centre, line, z)\n                if why:\n                    held.append((side, story, u, why))\n                    fixed.append((u, w))\n                else:\n                    movable.append((j, u, w))\n            # a window whose mirrored partner stays stays with it\n            keep = []\n            for (j, u, w) in movable:\n                if abs(u) > TOL and any(abs(fu + u) <= TOL and abs(fw - w) < 1e-6 for (fu, fw) in fixed):\n                    held.append((side, story, u, "its mirrored partner stays"))\n                    fixed.append((u, w))\n                else:\n                    keep.append((j, u, w))\n            movable = keep\n            if not movable:\n                final[(side, story)] = [u for (u, _w, _o) in here]\n                continue\n            junctions = _junctions(spec, side, story, centre, line)\n            # pair the movable windows: mirrored partners of one width, the centre line alone, the rest alone\n            groups, done = [], set()\n            for k, (j, u, w) in enumerate(movable):\n                if k in done:\n                    continue\n                done.add(k)\n                if abs(u) <= TOL:\n                    groups.append(((j,), (u,), w, "centre"))\n                    continue\n                m = next((m for m, (j2, u2, w2) in enumerate(movable)\n                          if m not in done and abs(u2 + u) <= TOL and abs(w2 - w) < 1e-6), None)\n                if m is None:\n                    groups.append(((j,), (u,), w, "alone"))\n                else:\n                    done.add(m)\n                    groups.append(((j, movable[m][0]), (u, movable[m][1]), w, "pair"))\n            placed = list(fixed)\n            taken = set()\n            new_u = {}\n            for (js, us, w, how) in groups:\n                if how == "pair":\n                    lo_u = min(us)\n                    cands = sorted((abs(b - lo_u), b) for b in below\n                                   if b < -TOL and _near(-b, below) and abs(b - lo_u) <= reach + 1e-9)\n                    targets = [(b, -b) for (_d, b) in cands]\n                elif how == "centre":\n                    targets = [(b,) for b in below if abs(b) <= TOL]\n                else:\n                    targets = [(b,) for (_d, b) in sorted((abs(b - us[0]), b) for b in below\n                                                          if abs(b - us[0]) <= reach + 1e-9)]\n                best = None\n                for ts in targets:\n                    if any(round(t, 3) in taken for t in ts):\n                        continue\n                    if all(_fits(t, w, placed + [(t2, w) for t2 in ts if t2 is not t], run, wt, junctions) is None\n                           for t in ts):\n                        best = ts\n                        break\n                if best is None:\n                    placed += [(u, w) for u in us]\n                    continue\n                pairs = list(zip(sorted(zip(us, js)), sorted(best)))\n                for ((u, j), t) in pairs:\n                    taken.add(round(t, 3))\n                    placed.append((t, w))\n                    if abs(t - u) > 1e-9:\n                        new_u[j] = (u, t)\n            for j, (u, t) in sorted(new_u.items()):\n                pos = round(t / run, 6)\n                assert abs(snap(pos * run) - t) < 1e-9, (side, story, t, pos)\n                wd["openings"][j]["pos"] = pos\n                moves.append((side, story, u, t))\n            final[(side, story)] = [new_u[j][1] if j in new_u else u for j, (u, _w, _o) in enumerate(here)]\n    return moves, held\n'}
NEW_FILES = {'migrations/migrate_front_rows.py': '#!/usr/bin/env python3\n"""\nmigrate_front_rows.py  --  a family\'s street face upstairs stands on its row\n============================================================================\nOne-shot, idempotent migration over specs/*.json for Deli Counter 0.296.0 (the\nfactory\'s roadmap 79, the facade planner; the walker of the slice\'s card shop:\n"yes to window rhythm").\n\nEach library spec -- not a Level Factory transient (`lf_*`) -- whose preset\n`facade_plan.FRONT_ROWS` names goes through `facade_plan.compose_front`: the\nstreet face of every upper storey people reach is re-laid one window to a\n`midrise` bay. People stand behind those windows, and the furniture was laid\nround the windows that were there, so a spec this changes is refurnished\n(`migrate_furnish_recipes.migrate`, measured a fixed point on every spec it\ntouches before this ran) and the pieces stand round the new ones.\n\n    python migrations/migrate_front_rows.py            # write specs/\n    python migrations/migrate_front_rows.py --check    # report only; exit 1 if any would change\n    python migrations/migrate_front_rows.py --dir D    # another spec directory\n"""\nimport glob\nimport io\nimport json\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, HERE)\n\nimport facade_plan               # noqa: E402\nimport migrate_furnish_recipes   # noqa: E402\n\n\ndef migrate(d):\n    """Compose and refurnish one spec dict in place: ``(faces, (removed, added))``, ``([], None)`` when the\n    face was already its row\'s."""\n    faces = facade_plan.compose_front(d)\n    if not any(before != after for _w, _s, before, after in faces):\n        return faces, None\n    return faces, migrate_furnish_recipes.migrate(d)\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    check = "--check" in argv\n    root = argv[argv.index("--dir") + 1] if "--dir" in argv else os.path.join(HERE, "specs")\n    changed = []\n    for p in sorted(glob.glob(os.path.join(root, "*.json"))):\n        name = os.path.basename(p)[:-len(".json")]\n        if name.startswith("lf_"):\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        if not isinstance(d, dict) or d.get("preset") not in facade_plan.FRONT_ROWS:\n            continue\n        before = json.dumps(d, sort_keys=True)\n        faces, furnished = migrate(d)\n        if json.dumps(d, sort_keys=True) == before:\n            continue\n        changed.append(name)\n        print("  %s: %s; refurnished %s" % (name, ", ".join("%s%d %d -> %d" % f for f in faces), furnished))\n        if not check:\n            io.open(p, "w", encoding="utf-8", newline="\\n").write(json.dumps(d, indent=1) + "\\n")\n    print("[front_rows] %d spec(s) %s" % (len(changed), "to compose" if check else "composed"))\n    return 1 if (check and changed) else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_front_rows.py': '"""A family\'s street face upstairs stands on its row (0.296.0; the factory\'s roadmap 79, and the walker of the slice).\n\nThe slice\'s card shop, card_shop_a01, stood two 1.4 m windows on its 20 m street face over an apartment, beside a bank\nwhose upper storey stands on 3.0 m bays (0.295.0). The walker: "yes to window rhythm". `facade_plan.FRONT_ROWS` names\nthe families whose street face is composed on every upper storey people reach; `compose_front` lays it as\n`compose_unreached` lays a storey nobody reaches, and the windows stay clear glass onto the rooms behind them.\n\nFAIL ON 0.295.1: there is no `compose_front` or `FRONT_ROWS`, and the card shop\'s spec still carries two windows on its\nstreet face upstairs. The spec tests read the spec alone, so they fail for that reason and not for an import.\n"""\nimport copy\nimport json\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, HERE)\n\nimport spec_loader   # noqa: E402\n\n\ndef _spec(name):\n    return json.load(open(os.path.join(HERE, "specs", name + ".json"), encoding="utf-8"))\n\n\ndef _cut(d, story):\n    """{side: openings of `side` on `story` in metres from the wall\'s centre, as the builder cuts them}."""\n    s = spec_loader.spec_from_dict(d)\n    out = {}\n    for w in s.ext_walls:\n        if w.story == story:\n            run = s.footprint_x if w.wall in ("N", "S") else s.footprint_y\n            out[w.wall] = sorted(round(round(o.pos * run / s.grid) * s.grid, 3) for o in w.openings)\n    return out\n\n\ndef test_the_card_shops_street_face_upstairs_stands_on_three_metre_bays():\n    cut = _cut(_spec("card_shop_a01"), 1)\n    assert cut["S"] == [-7.5, -4.5, -1.5, 1.5, 4.5, 7.5]\n    # its other faces upstairs, and its ground floor, are as the preset authored them\n    assert cut["N"] == [0.0] and cut["W"] == [0.0] and cut["E"] == [0.0]\n    assert _cut(_spec("card_shop_a01"), 0)["S"] == [-7.0, -3.0, 4.0]\n\n\ndef test_the_windows_are_clear_glass_onto_rooms_people_reach():\n    """Not a facade: the storey has its apartment and its stair, so the emitter keeps the panes clear and lit."""\n    import facade_plan\n    d = _spec("card_shop_a01")\n    assert facade_plan.unreached_storeys(spec_loader.spec_from_dict(d)) == []\n    front = [w for w in d["ext_walls"] if w["wall"] == "S" and w["story"] == 1][0]["openings"]\n    assert all(o["kind"] == "window" and o.get("material") == "glass" and "pane" not in o for o in front)\n    assert {(o["width"], o["sill"]) for o in front} == {(1.4, 1.0)}\n\n\ndef test_the_furniture_was_laid_round_the_windows_that_are_built():\n    """Composing again moves nothing, and so refurnishing moves nothing: every piece stands where `furnish` puts it\n    with these windows in the wall."""\n    import facade_plan\n    import migrate_furnish_recipes\n    d = _spec("card_shop_a01")\n    before = json.dumps(d, sort_keys=True)\n    assert all(b == a for _w, _s, b, a in facade_plan.compose_front(d))\n    migrate_furnish_recipes.migrate(d)\n    assert json.dumps(d, sort_keys=True) == before\n\n\ndef test_the_preset_builds_the_same_face():\n    import presets\n    spec = presets.make("card_shop", enrich=False)\n    assert _cut(spec, 1)["S"] == [-7.5, -4.5, -1.5, 1.5, 4.5, 7.5]\n\n\ndef test_only_a_named_family_and_never_a_held_face():\n    """A family `FRONT_ROWS` does not name is untouched, and so is a face whose window a drape hangs over -- it was\n    hung for the windows that are there."""\n    import facade_plan\n    pawn = _spec("pawn_shop_a01")\n    before = json.dumps(pawn, sort_keys=True)\n    assert facade_plan.compose_front(pawn) == [] and json.dumps(pawn, sort_keys=True) == before\n\n    d = copy.deepcopy(_spec("card_shop_a01"))\n    front = [w for w in d["ext_walls"] if w["wall"] == "S" and w["story"] == 1][0]\n    front["openings"] = front["openings"][:2]\n    x = front["openings"][0]["pos"] * float(d["footprint_x"])\n    z = float(d["story_height"]) + 1.0 + 0.7\n    d["volumes"].append({"name": "window_drape_test", "x": x, "y": -float(d["footprint_y"]) / 2.0 + 0.2, "z": z,\n                         "size_x": 1.6, "size_y": 0.1, "size_z": 1.6})\n    held = json.dumps(d, sort_keys=True)\n    facade_plan.compose_front(d)\n    assert json.dumps(d, sort_keys=True) == held\n'}


def _sha(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: %s/%s has mixed line endings; nothing written" % (REPO.name, name))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text) != PINS[name]:
        raise SystemExit("REFUSED: %s/%s is %s, not the %s this patch was written against; nothing written"
                         % (REPO.name, name, _sha(text), PINS[name]))
    return text, crlf > 0


def main():
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: %s/%s: the anchor at %s is there %d times; nothing written"
                                 % (REPO.name, name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name, text in WHOLE.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: %s/%s exists already; nothing written" % (REPO.name, name))
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).parent.mkdir(parents=True, exist_ok=True)
        (REPO / name).write_bytes(text.encode("utf-8"))
    print("%s: %d files edited, %d written" % (REPO.name, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
